def scene(i,s,img='assets/education.png'):
 q=s[5]; cid=f's{i+1:02}'; art=''
 if q is not None:
  art=f'<div class="art q{q}"><img src="{img}" alt="'+['人工植牙的牙冠、連接零件與骨內植體剖面概念圖','患者與牙醫討論治療','牙間刷清潔牙齒鄰接面概念圖','軟質食物、飲水與隔布冰敷用品'][q]+'">'
  if i==1: art+='<span class="label crown">牙冠</span><span class="label abut">支台齒</span><span class="label fixture">植體</span>'
  if i in [5,6,7]:art+='<div class="phase">'+['植體置入骨內','等待骨整合','牙冠製作與調整'][i-5]+'</div>'
  art+='</div><div class="art-note">概念示意，實際比例與治療方式因人而異</div>'
 extra=''
 if i in [3,5,6,7]:
  extra='<div class="stage-step"><strong>'+['01','02','03','04'][[3,5,6,7].index(i)]+'</strong><span>'+['評估與準備','植入與傷口照護','等待骨整合','裝牙與追蹤'][[3,5,6,7].index(i)]+'</span><div class="timeline-line"><div class="timeline-fill"></div></div></div>'
 points=''.join('<li>'+h(t)+'</li>' for t in s[3])
 return f'<section id="{cid}" class="scene {"no-art" if q is None else ""} {"urgent" if i==10 else ""}" data-composition-id="{cid}" data-start="{i*10}" data-duration="10" data-width="1920" data-height="1080" data-label="{h(s[0])}"><div class="eyebrow" data-anim>{h(s[1])}</div><div class="num">{i+1:02} / {len(S):02}</div><div class="copy"><h2 data-anim>{h(s[0])}</h2><p class="main" data-anim>{h(s[2])}</p><ul class="points" data-anim>{points}</ul>{extra}</div>{art}<div class="takeaway" data-anim>{h(s[4])}</div><div class="foot">人工植牙患者衛教　／　一般資訊，依醫師個別指示調整</div></section>'
